theorem HasCauchyPV.unique {f : ℂ → ℂ} {γ : PiecewiseC1Path x y} {z₀ : ℂ}
    {L₁ L₂ : ℂ} (h₁ : HasCauchyPV f γ z₀ L₁) (h₂ : HasCauchyPV f γ z₀ L₂) :
    L₁ = L₂

theorem cpvIntegrand_eq_cpvIntegrandOn_singleton {f : ℂ → ℂ} {γ : ℝ → ℂ} {z₀ : ℂ}
    {ε : ℝ} {t : ℝ} :
    cpvIntegrand f γ z₀ ε t = cpvIntegrandOn {z₀} f γ ε t

theorem hasCauchyPVOn_of_avoids {S : Finset ℂ} {f : ℂ → ℂ} {γ : PiecewiseC1Path x y}
    (hδ : ∃ δ > 0, ∀ s ∈ S, ∀ t ∈ Icc (0 : ℝ) 1, δ ≤ ‖γ t - s‖) :
    HasCauchyPVOn S f γ (γ.contourIntegral f)

theorem hasCauchyPV_of_avoids {f : ℂ → ℂ} {γ : PiecewiseC1Path x y} {z₀ : ℂ}
    (hδ : ∃ δ > 0, ∀ t ∈ Icc (0 : ℝ) 1, δ ≤ ‖γ t - z₀‖) :
    HasCauchyPV f γ z₀ (γ.contourIntegral f)

theorem HasCauchyPV'.cauchyPV_eq {f : ℂ → ℂ} {γ : ℝ → ℂ}
    {a b : ℝ} {z₀ : ℂ} {L : ℂ} (h : HasCauchyPV' f γ a b z₀ L) :
    cauchyPrincipalValue' f γ a b z₀ = L

theorem HasCauchyPV'.congr_along_curve {f g : ℂ → ℂ} {γ : ℝ → ℂ} {a b : ℝ} {z₀ : ℂ} {L : ℂ}
    (h : HasCauchyPV' f γ a b z₀ L) (h_eq : ∀ t, f (γ t) = g (γ t)) :
    HasCauchyPV' g γ a b z₀ L

theorem HasCauchyPV'.const_mul {f : ℂ → ℂ} {γ : ℝ → ℂ} {a b : ℝ} {z₀ : ℂ} {L : ℂ}
    (h : HasCauchyPV' f γ a b z₀ L) (c : ℂ) :
    HasCauchyPV' (fun z => c * f z) γ a b z₀ (c * L)

theorem HasCauchyPV'.mul_const {f : ℂ → ℂ} {γ : ℝ → ℂ} {a b : ℝ} {z₀ : ℂ} {L : ℂ}
    (h : HasCauchyPV' f γ a b z₀ L) (c : ℂ) :
    HasCauchyPV' (fun z => f z * c) γ a b z₀ (L * c)

theorem HasCauchyPV'.unique {f : ℂ → ℂ} {γ : ℝ → ℂ} {a b : ℝ} {z₀ : ℂ}
    {L₁ L₂ : ℂ} (h₁ : HasCauchyPV' f γ a b z₀ L₁) (h₂ : HasCauchyPV' f γ a b z₀ L₂) :
    L₁ = L₂

theorem dixonFunction_eq_dixonH1 {f : ℂ → ℂ} {U : Set ℂ}
    {γ : PiecewiseC1Path x x} {w : ℂ} (hw : w ∈ U) :
    dixonFunction f U γ w = dixonH1 f γ w

theorem dixonH2_differentiableAt_of_regular {f : ℂ → ℂ}
    {γ : PiecewiseC1Path x x} {w : ℂ}
    (hoff : ∀ t ∈ Icc (0 : ℝ) 1, γ t ≠ w)
    (hf_cont : ContinuousOn f (γ.toPath.extend '' Icc (0 : ℝ) 1))
    {K : NNReal} (hLip : LipschitzWith K γ.toPath.extend) :
