    (hδ : 0 ≤ δ) (h_far : ε ≤ ‖γ (t₀ - δ) - s‖) :
    (t₀ - δ) ∈ {t ∈ Icc (t₀ - δ) t₀ | ε ≤ ‖γ t - s‖}

theorem firstExitTimeRight_set_nonempty
    {γ : ℝ → ℂ} {t₀ δ ε : ℝ} {s : ℂ}
    (hδ : 0 ≤ δ) (h_far : ε ≤ ‖γ (t₀ + δ) - s‖) :
    (t₀ + δ) ∈ {t ∈ Icc t₀ (t₀ + δ) | ε ≤ ‖γ t - s‖}

lemma deriv_deviation_bound_of_C2 {γ : ℝ → ℂ} {t₀ : ℝ} {L : ℂ}
    (hγ_C2 : ContDiffAt ℝ 2 γ t₀) (hγ_deriv : deriv γ t₀ = L) :
    ∃ K δ, 0 < δ ∧ ∀ t, |t - t₀| < δ → ‖deriv γ t - L‖ ≤ K * |t - t₀|

theorem HasCauchyPVOn'.cauchyPVOn_eq {S : Finset ℂ} {f : ℂ → ℂ} {γ : ℝ → ℂ}
    {a b : ℝ} {L : ℂ} (h : HasCauchyPVOn' S f γ a b L) :
    cauchyPrincipalValueOn S f γ a b = L

theorem HasCauchyPVOn'.unique {S : Finset ℂ} {f : ℂ → ℂ} {γ : ℝ → ℂ} {a b : ℝ}
    {L₁ L₂ : ℂ} (h₁ : HasCauchyPVOn' S f γ a b L₁) (h₂ : HasCauchyPVOn' S f γ a b L₂) :
    L₁ = L₂

theorem aEStronglyMeasurable_of_continuousOn_off_finite {f : ℝ → ℂ} {a b : ℝ} {P : Finset ℝ}
