    ∃ ε > 0, ∀ w ∈ Metric.ball w₀ ε, ∀ t ∈ Icc (0 : ℝ) 1, ε ≤ ‖γ t - w‖

theorem hasGeneralizedWindingNumber_of_hasCauchyPV {γ : PiecewiseC1Path x y} {z₀ L : ℂ}
    (h : HasCauchyPV (fun z => (z - z₀)⁻¹) γ z₀ L) :
    HasGeneralizedWindingNumber γ z₀ ((2 * ↑Real.pi * I)⁻¹ * L)

theorem deriv_intervalIntegrable_of_lipschitz (γP : PiecewiseC1Path x x) {K : NNReal}
    (hLip : LipschitzWith K γP.toPath.extend) :
