theorem fdBoundary_contourIntegral_interior_eq {H : ℝ}
    (_hH : H > Real.sqrt 3 / 2) {z : ℂ} (hz : FDStrictInterior z H)
    {γ : PiecewiseC1Path (fdStart H) (fdStart H)}
    (hγ : ∀ t ∈ Icc (0 : ℝ) 1, γ.toPath.extend t = fdBoundaryFun H t) :
