theorem transfer_integral {H : ℝ} (z : ℂ) {a b : ℝ}
    (hab : a ≤ b) (ha : 0 ≤ a) (hb : b ≤ 1)
    {γ : PiecewiseC1Path (fdStart H) (fdStart H)}
    (hγ : ∀ t ∈ Icc (0 : ℝ) 1, γ.toPath.extend t = fdBoundaryFun H t) :
    ∫ t in a..b, (γ.toPath.extend t - z)⁻¹ * deriv γ.toPath.extend t =
    ∫ t in a..b, (fdBoundaryFun H t - z)⁻¹ * deriv (fdBoundaryFun H) t

lemma fdBoundary_H_eq_seg4_H {H t : ℝ}
    (ht3 : 3 < t) (ht4 : t ≤ 4) :
    fdBoundary_H H t = fdBoundary_seg4_H H t

theorem segRatio_eq_full {γ : ℝ → ℂ} {w : ℂ} {s_j s_jp1 t : ℝ}
    (h : s_j ≤ s_jp1) (ht : s_jp1 ≤ t) :
    segRatio γ w s_j s_jp1 t = (γ s_jp1 - w) / (γ s_j - w)

theorem segRatio_eq_one_of_le {γ : ℝ → ℂ} {w : ℂ} {s_j s_jp1 t : ℝ}
    (h : s_j ≤ s_jp1) (ht : t ≤ s_j) (h_ne : γ s_j - w ≠ 0) :
    segRatio γ w s_j s_jp1 t = 1

theorem segRatio_eq_self_div {γ : ℝ → ℂ} {w : ℂ} {s_j s_jp1 t : ℝ}
    (ht_lo : s_j ≤ t) (ht_hi : t ≤ s_jp1) :
    segRatio γ w s_j s_jp1 t = (γ t - w) / (γ s_j - w)

